template <class T>
void FABLE_FASTCALL GFSmoothTowards(const T& target, const T& max_step, T& current)
{
    T step = target - current;
    if (step < -max_step)
        step = -max_step;
    else if (step > max_step)
        step = max_step;
    current += step;
    if (step > 0) {
        if (current > target)
            current = target;
    } else {
